document.addEventListener("DOMContentLoaded",function(){const e=document.querySelector(".wrap .wp-heading-inline + .page-title-action");if(e){const t=document.createElement("a");t.href=AAE_PAGE_IMPORT.page_url,t.style.top="2px",t.style.left="5px",t.style.borderColor="#fc6848",t.id="aae-heading-button",t.className="page-title-action",t.innerHTML=`\n                <div style="display: flex; justify-content: center; align-items: center; gap: 9px"><img src="${AAE_PAGE_IMPORT.logo}" /> <span style="font-wight: 500; color: #fc6848">AAE Import</span></div>\n                `,e.after(t)}});